# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs, factor=3):
    return [v * factor for v in xs]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: intake
def intake(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(sift(emit(shape(digest(fold(raw))))))

